import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';
import 'package:dio/dio.dart';
import 'package:flutter/material.dart';
import 'package:path_provider/path_provider.dart';

/// Persistent disk cache shared by network images in the passenger app.
///
/// Image URLs generated by the API use unique names when an image is replaced,
/// so a long freshness period avoids repeat downloads without hiding updates.
class PersistentNetworkImageCache {
  PersistentNetworkImageCache._();

  static const _freshFor = Duration(days: 365);
  static const _maximumFiles = 400;
  static const _directoryName = 'yemen_drive_network_images';
  static final Dio _dio = Dio(
    BaseOptions(
      connectTimeout: const Duration(seconds: 10),
      receiveTimeout: const Duration(seconds: 20),
    ),
  );
  static final Map<String, Future<File>> _inFlight = <String, Future<File>>{};
  static final Set<String> _refreshing = <String>{};
  static Future<Directory>? _cacheDirectory;
  static Future<void>? _pruning;
  static DateTime? _lastPrune;

  static Future<Directory> _directory() => _cacheDirectory ??= () async {
        final support = await getApplicationSupportDirectory();
        return Directory(
          '${support.path}${Platform.pathSeparator}$_directoryName',
        ).create(recursive: true);
      }()
          .catchError((Object error) {
        _cacheDirectory = null;
        throw error;
      });

  static Future<File> fileFor(String imageUrl) {
    final url = imageUrl.trim();
    final uri = Uri.tryParse(url);
    if (uri == null || (uri.scheme != 'http' && uri.scheme != 'https')) {
      return Future<File>.error(ArgumentError.value(imageUrl, 'imageUrl'));
    }

    final key = sha256.convert(utf8.encode(url)).toString();
    final active = _inFlight[key];
    if (active != null) return active;

    final request = _loadFile(url, key);
    _inFlight[key] = request;
    return request.whenComplete(() => _inFlight.remove(key));
  }

  static Future<File> _loadFile(String url, String key) async {
    final cacheDirectory = await _directory();
    final cachedFile = File(
      '${cacheDirectory.path}${Platform.pathSeparator}$key.image',
    );

    if (await cachedFile.exists() && await cachedFile.length() > 0) {
      final age = DateTime.now().difference(await cachedFile.lastModified());
      if (age < _freshFor) return cachedFile;
      _refreshStaleFile(url, key, cacheDirectory, cachedFile);
      return cachedFile;
    }

    return _download(url, key, cacheDirectory, cachedFile);
  }

  static void _refreshStaleFile(
    String url,
    String key,
    Directory cacheDirectory,
    File cachedFile,
  ) {
    if (!_refreshing.add(key)) return;
    unawaited(() async {
      try {
        await _download(url, key, cacheDirectory, cachedFile);
      } catch (_) {
        // Keep serving the stale image when the device is offline.
      } finally {
        _refreshing.remove(key);
      }
    }());
  }

  static Future<File> _download(
    String url,
    String key,
    Directory cacheDirectory,
    File cachedFile,
  ) async {
    final temporaryFile = File(
      '${cachedFile.path}.${DateTime.now().microsecondsSinceEpoch}.tmp',
    );
    try {
      final response = await _dio.download(
        url,
        temporaryFile.path,
        options: Options(
          headers: const <String, String>{'Accept': 'image/*'},
          validateStatus: (status) =>
              status != null && status >= 200 && status < 300,
        ),
      );
      if (response.statusCode == null ||
          response.statusCode! < 200 ||
          response.statusCode! >= 300 ||
          !await temporaryFile.exists() ||
          await temporaryFile.length() == 0) {
        throw StateError('The image response was empty or unsuccessful.');
      }

      if (await cachedFile.exists()) await cachedFile.delete();
      final savedFile = await temporaryFile.rename(cachedFile.path);
      _schedulePrune(cacheDirectory);
      return savedFile;
    } catch (_) {
      if (await cachedFile.exists() && await cachedFile.length() > 0) {
        return cachedFile;
      }
      rethrow;
    } finally {
      if (await temporaryFile.exists()) await temporaryFile.delete();
    }
  }

  static void _schedulePrune(Directory directory) {
    if (_pruning != null ||
        (_lastPrune != null &&
            DateTime.now().difference(_lastPrune!) <
                const Duration(minutes: 5))) {
      return;
    }
    _lastPrune = DateTime.now();
    _pruning = _prune(directory).catchError((Object _) {
      // Cache housekeeping must never delay or fail a successfully loaded image.
    }).whenComplete(() => _pruning = null);
  }

  static Future<void> _prune(Directory directory) async {
    final files = await directory
        .list(followLinks: false)
        .where((entry) => entry is File && entry.path.endsWith('.image'))
        .cast<File>()
        .toList();
    if (files.length <= _maximumFiles) return;

    final datedFiles = await Future.wait(
      files.map(
          (file) async => (file: file, modified: await file.lastModified())),
    );
    datedFiles.sort((left, right) => right.modified.compareTo(left.modified));
    for (final entry in datedFiles.skip(_maximumFiles)) {
      try {
        await entry.file.delete();
      } on FileSystemException {
        // A file currently being decoded can be removed on a later cache pass.
      }
    }
  }
}

class PersistentNetworkImage extends StatefulWidget {
  const PersistentNetworkImage(
    this.imageUrl, {
    this.fit,
    this.filterQuality = FilterQuality.medium,
    this.width,
    this.height,
    this.errorBuilder,
    super.key,
  });

  final String imageUrl;
  final BoxFit? fit;
  final FilterQuality filterQuality;
  final double? width;
  final double? height;
  final ImageErrorWidgetBuilder? errorBuilder;

  @override
  State<PersistentNetworkImage> createState() => _PersistentNetworkImageState();
}

class _PersistentNetworkImageState extends State<PersistentNetworkImage> {
  late Future<File> _imageFile;

  @override
  void initState() {
    super.initState();
    _imageFile = PersistentNetworkImageCache.fileFor(widget.imageUrl);
  }

  @override
  void didUpdateWidget(covariant PersistentNetworkImage oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.imageUrl != widget.imageUrl) {
      _imageFile = PersistentNetworkImageCache.fileFor(widget.imageUrl);
    }
  }

  @override
  Widget build(BuildContext context) => FutureBuilder<File>(
        future: _imageFile,
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return widget.errorBuilder?.call(
                  context,
                  snapshot.error!,
                  snapshot.stackTrace,
                ) ??
                const SizedBox.shrink();
          }
          final file = snapshot.data;
          if (file == null) return const SizedBox.shrink();
          return LayoutBuilder(builder: (context, constraints) {
            final ratio = MediaQuery.devicePixelRatioOf(context);
            int? pixels(double dimension) => dimension.isFinite && dimension > 0
                ? (dimension * ratio).ceil().clamp(1, 2048)
                : null;
            final width = pixels(widget.width ?? constraints.maxWidth);
            final height = pixels(widget.height ?? constraints.maxHeight);
            final ImageProvider provider = width == null && height == null
                ? FileImage(file)
                : ResizeImage(FileImage(file),
                    width: width,
                    height: height,
                    policy: ResizeImagePolicy.fit);
            return Image(
              image: provider,
              fit: widget.fit,
              filterQuality: widget.filterQuality,
              width: widget.width,
              height: widget.height,
              errorBuilder: widget.errorBuilder,
              gaplessPlayback: true,
            );
          });
        },
      );
}
